import React, { useState, useEffect } from "react";
import Sidebar from "../../components/Sidebar_p-a";
import HeaderMovimientos from " ../../components/HeaderMovimientos";
import "../../components/admin.css"; 

// URL base de tu API de Django para productos
const API_URL = 'http://127.0.0.1:8000/api/productos';

export default function FormularioEntradaProducto() {
    // 1. Estado inicial para almacenar todos los datos del formulario
    const [formData, setFormData] = useState({
        id_producto: '',
        nom_producto: '',
        precio_unitario: '',
        stock_actual: '',
        cantidad_ingresada: '',
        proveedor: '', // Campo extra, no guardado en el modelo Producto
        fecha: new Date().toISOString().split('T')[0],
        observacion: '' // Campo extra, no guardado en el modelo Producto
    });

    // 2. Estado para el mensaje de carga, error o éxito
    const [mensaje, setMensaje] = useState(null);

    // Función para manejar los cambios en cualquier campo
    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prevData => ({
            ...prevData,
            [name]: value
        }));
    };

    // ===============================================
    // LÓGICA DE CONSULTA (Función Clave)
    // ===============================================
    useEffect(() => {
        // La consulta solo se ejecuta si el ID no está vacío
        if (formData.id_producto && parseInt(formData.id_producto) > 0) {
            setMensaje({ type: 'info', text: 'Buscando producto...' });

            // Realiza la petición GET al endpoint específico: /api/productos/ID/
            fetch(`${API_URL}/${formData.id_producto}/`) 
                .then(response => {
                    if (response.status === 404) {
                        setMensaje({ type: 'warning', text: `ID ${formData.id_producto} no encontrado. Creando nuevo producto.` });
                        // Resetea campos clave para permitir entrada de producto nuevo
                        setFormData(prevData => ({
                            ...prevData,
                            nom_producto: '',
                            precio_unitario: '',
                            stock_actual: ''
                        }));
                        return null; // Detiene el flujo
                    }
                    if (!response.ok) {
                        throw new Error('Error al conectar con la API');
                    }
                    return response.json();
                })
                .then(data => {
                    if (data) {
                        // Rellena los campos con los datos obtenidos de Django
                        setFormData(prevData => ({
                            ...prevData,
                            nom_producto: data.nom_producto,
                            precio_unitario: data.precio_unitario,
                            stock_actual: data.stock_actual,
                            // Mantenemos la cantidad ingresada y otros campos específicos
                        }));
                        setMensaje({ type: 'success', text: `Producto encontrado. Stock actual: ${data.stock_actual}` });
                    }
                })
                .catch(error => {
                    console.error("Error de búsqueda:", error);
                    setMensaje({ type: 'error', text: 'Error en la conexión con el servidor.' });
                });

        } else if (formData.id_producto === '') {
            // Limpia los campos si el ID se borra
            setMensaje(null);
            setFormData(prevData => ({
                ...prevData,
                nom_producto: '',
                precio_unitario: '',
                stock_actual: ''
            }));
        }
    }, [formData.id_producto]); // <<-- SE EJECUTA cuando el ID cambia

    // ===============================================
    // LÓGICA DE ENVÍO (Guardar/Actualizar Stock)
    // ===============================================
    const handleSubmit = async (e) => {
        e.preventDefault();
        setMensaje({ type: 'info', text: 'Procesando entrada de inventario...' });

        const isExistingProduct = !!formData.stock_actual;

        const url = isExistingProduct ? `${API_URL}/${formData.id_producto}/` : `${API_URL}/`;

        // 1. Determinar el nuevo stock total
        // ParseInt se asegura de que sean números enteros
        const currentStock = parseInt(formData.stock_actual || '0');
        const incomingQuantity = parseInt(formData.cantidad_ingresada);
        const newStockTotal = currentStock + incomingQuantity;

        // 2. Preparar los datos para enviar a Django
        const dataToSend = {
            // Nota: Debes enviar las FKs (id_categoria, id_clasificacion) como IDs, 
            // pero como este formulario solo actualiza stock, asumiremos que ya existen.
            nom_producto: formData.nom_producto,
            precio_unitario: parseInt(formData.precio_unitario),
            stock_actual: String(newStockTotal), // Tu modelo espera un CharField (String)
            // Agrega otros campos obligatorios aquí si son necesarios para la actualización
        };

        const method = isExistingProduct ? 'PATCH' : 'POST'; // Usar PATCH para actualizar, POST para crear

        try {
            const response = await fetch(url, {
                method: method,
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(dataToSend),
            });

            if (!response.ok) {
                // Si hay un error, el backend lo detallará
                const errorData = await response.json();
                throw new Error(JSON.stringify(errorData));
            }

            const result = await response.json();
            setMensaje({ type: 'success', text: `Inventario actualizado con éxito. Nuevo stock: ${result.stock_actual}` });

            // Opcional: Recargar o limpiar el formulario
            setFormData(prevData => ({ ...prevData, stock_actual: result.stock_actual, cantidad_ingresada: '', proveedor: '', observacion: '' }));

        } catch (error) {
            console.error("Error al guardar:", error);
            setMensaje({ type: 'error', text: `Error al procesar: ${error.message || 'Verifica la consola.'}` });
        }
    };

    return (
        <div className="dashboard-layout">
            <Sidebar />
            <main className="contenido">
                <HeaderMovimientos />

                {/* Contenedor de mensajes */}
                {mensaje && (
                    <div className={`mensaje ${mensaje.type}`}>
                        {mensaje.text}
                    </div>
                )}

                <section className="cuadro-blanco form-producto">

                    <form className="formulario" onSubmit={handleSubmit}>

                        {/* ID Producto (Campo clave) */}
                        <div className="campo">
                            <label htmlFor="id_producto">ID del Producto</label>
                            <input 
                                type="number" 
                                id="id_producto" 
                                name="id_producto" 
                                placeholder="Ingrese el ID del producto" 
                                value={formData.id_producto}
                                onChange={handleChange}
                                required 
                            />
                        </div>

                        {/* Nombre del Producto (se rellena automáticamente) */}
                        <div className="campo">
                            <label htmlFor="nom_producto">Nombre del Producto</label>
                            <input 
                                type="text" 
                                id="nom_producto" 
                                name="nom_producto" 
                                placeholder="Ejemplo: Sábana Paw Patrol" 
                                value={formData.nom_producto}
                                onChange={handleChange}
                                readOnly={!!formData.stock_actual && !mensaje?.text.includes('no encontrado')} // Desactivar si existe
                                required 
                            />
                        </div>
                        {/* ... (resto de los campos del formulario usando value={formData.nombre_campo} y onChange={handleChange}) ... */}

                        {/* Stock Actual (solo lectura) */}
                        <div className="campo">
                            <label htmlFor="stock_actual">Stock Actual (Sistema)</label>
                            <input 
                                type="text" 
                                id="stock_actual" 
                                name="stock_actual" 
                                placeholder="Stock actual del producto" 
                                value={formData.stock_actual}
                                readOnly={true} 
                            />
                        </div>

                        {/* Cantidad ingresada (Nuevo stock a sumar) */}
                        <div className="campo">
                            <label htmlFor="cantidad_ingresada">Cantidad ingresada</label>
                            <input 
                                type="number" 
                                id="cantidad_ingresada" 
                                name="cantidad_ingresada" 
                                placeholder="Cantidad de unidades que entran" 
                                value={formData.cantidad_ingresada}
                                onChange={handleChange}
                                required 
                            />
                        </div>

                        {/* Proveedor */}
                        <div className="campo">
                            <label htmlFor="proveedor">Proveedor</label>
                            <input 
                                type="text" 
                                id="proveedor" 
                                name="proveedor" 
                                placeholder="Nombre del proveedor" 
                                value={formData.proveedor}
                                onChange={handleChange}
                                required 
                            />
                        </div>

                        {/* ... (otros campos como fecha, observaciones) ... */}

                        {/* Botones de acción */}
                        <div className="botones">
                            <button type="submit" className="btn-guardar">
                                <i className="fa-solid fa-floppy-disk"></i> Guardar
                            </button>
                            <button type="reset" className="btn-cancelar">
                                <i className="fa-solid fa-xmark"></i> Cancelar
                            </button>
                        </div>
                    </form>
                </section>
            </main>
        </div>
    );
}
